document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("inv-grid");n&&(n.innerHTML=INVENTIONS.map(n=>`\n        <a class="inv-card" href="${n.link}">\n            <span class="inv-card-icon">${n.icon}</span>\n            <h3>${n.title}</h3>\n            <p class="inv-card-era">${n.era}</p>\n            <p class="inv-card-summary">${n.summary}</p>\n            <span class="inv-card-cta">Explore →</span>\n        </a>\n    `).join(""))});